50|int ares_parse_a_reply(const unsigned char *abuf, int alen,
51|                       struct hostent **host,
52|                       struct ares_addrttl *addrttls, int *naddrttls)
53|{
54|  struct ares_addrinfo ai;
55|  struct ares_addrinfo_node *next;
56|  struct ares_addrinfo_cname *next_cname;
57|  char **aliases = NULL;
58|  char *question_hostname = NULL;
59|  struct hostent *hostent = NULL;
60|  struct in_addr *addrs = NULL;
61|  int naliases = 0, naddrs = 0, alias = 0, i;
62|  int cname_ttl = INT_MAX;
63|  int status;
64|
65|  memset(&ai, 0, sizeof(ai));
66|
67|  status = ares__parse_into_addrinfo2(abuf, alen, &question_hostname, &ai);
68|  if (status != ARES_SUCCESS)
69|    {
70|      ares_free(question_hostname);
71|
72|      if (naddrttls)
73|        {
74|          *naddrttls = 0;
75|        }
76|
77|      return status;
78|    }
79|
80|  hostent = ares_malloc(sizeof(struct hostent));
81|  if (!hostent)
82|    {
83|      goto enomem;
84|    }
85|
86|  next = ai.nodes;
87|  while (next)
88|    {
89|      if (next->ai_family == AF_INET)
90|        {
91|          ++naddrs;
92|        }
93|      next = next->ai_next;
94|    }
95|
96|  next_cname = ai.cnames;
97|  while (next_cname)
98|    {
99|      if(next_cname->alias)
100|        ++naliases;
101|      next_cname = next_cname->next;
102|    }
103|
104|  aliases = ares_malloc((naliases + 1) * sizeof(char *));
105|  if (!aliases)
106|    {
107|      goto enomem;
108|    }
109|
110|  if (naliases)
111|    {
112|      next_cname = ai.cnames;
113|      while (next_cname)
114|        {
115|          if(next_cname->alias)
116|            aliases[alias++] = strdup(next_cname->alias);
117|          if(next_cname->ttl < cname_ttl)
118|            cname_ttl = next_cname->ttl;
119|          next_cname = next_cname->next;
120|        }
121|    }
122|
123|  aliases[alias] = NULL;
124|
125|  hostent->h_addr_list = ares_malloc((naddrs + 1) * sizeof(char *));
126|  if (!hostent->h_addr_list)
127|    {
128|      goto enomem;
129|    }
130|
131|  for (i = 0; i < naddrs + 1; ++i)
132|    {
133|      hostent->h_addr_list[i] = NULL;
134|    }
135|
136|  if (ai.cnames)
137|    {
138|      hostent->h_name = strdup(ai.cnames->name);
139|      ares_free(question_hostname);
140|    }
141|  else
142|    {
143|      hostent->h_name = question_hostname;
144|    }
145|
146|  hostent->h_aliases = aliases;
147|  hostent->h_addrtype = AF_INET;
148|  hostent->h_length = sizeof(struct in_addr);
149|
150|  if (naddrs)
151|    {
152|      addrs = ares_malloc(naddrs * sizeof(struct in_addr));
153|      if (!addrs)
154|        {
155|          goto enomem;
156|        }
157|
158|      i = 0;
159|      next = ai.nodes;
160|      while (next)
161|        {
162|          if (next->ai_family == AF_INET)
163|            {
164|              hostent->h_addr_list[i] = (char *)&addrs[i];
165|              memcpy(hostent->h_addr_list[i],
166|                     &(CARES_INADDR_CAST(struct sockaddr_in *, next->ai_addr)->sin_addr),
167|                     sizeof(struct in_addr));
168|              if (naddrttls && i < *naddrttls)
169|                {
170|                  if (next->ai_ttl > cname_ttl)
171|                    addrttls[i].ttl = cname_ttl;
172|                  else
173|                    addrttls[i].ttl = next->ai_ttl;
174|
175|                  memcpy(&addrttls[i].ipaddr,
176|                         &(CARES_INADDR_CAST(struct sockaddr_in *, next->ai_addr)->sin_addr),
177|                         sizeof(struct in_addr));
178|                }
179|              ++i;
180|            }
181|          next = next->ai_next;
182|        }
183|      if (i == 0)
184|        {
185|          ares_free(addrs);
186|        }
187|    }
188|
189|  if (host)
190|    {
191|      *host = hostent;
192|    }
193|  else
194|    {
195|      ares_free_hostent(hostent);
196|    }
197|
198|  if (naddrttls)
199|    {
200|      *naddrttls = naddrs;
201|    }
202|
203|  ares__freeaddrinfo_cnames(ai.cnames);
204|  ares__freeaddrinfo_nodes(ai.nodes);
205|  return ARES_SUCCESS;
206|
207|enomem:
208|  ares_free(aliases);
209|  ares_free(hostent);
210|  ares__freeaddrinfo_cnames(ai.cnames);
211|  ares__freeaddrinfo_nodes(ai.nodes);
212|  ares_free(question_hostname);
213|  return ARES_ENOMEM;
214|}

48|int ares__parse_into_addrinfo2(const unsigned char *abuf,
49|                               int alen,
50|                               char **question_hostname,
51|                               struct ares_addrinfo *ai)
52|{
53|  unsigned int qdcount, ancount;
54|  int status, i, rr_type, rr_class, rr_len, rr_ttl;
55|  int got_a = 0, got_aaaa = 0, got_cname = 0;
56|  long len;
57|  const unsigned char *aptr;
58|  char *hostname, *rr_name = NULL, *rr_data;
59|  struct ares_addrinfo_cname *cname, *cnames = NULL;
60|  struct ares_addrinfo_node *node, *nodes = NULL;
61|  struct sockaddr_in *sin;
62|  struct sockaddr_in6 *sin6;
63|
64|  *question_hostname = NULL;
65|
66|  /* Give up if abuf doesn't have room for a header. */
67|  if (alen < HFIXEDSZ)
68|    return ARES_EBADRESP;
69|
70|  /* Fetch the question and answer count from the header. */
71|  qdcount = DNS_HEADER_QDCOUNT(abuf);
72|  ancount = DNS_HEADER_ANCOUNT(abuf);
73|  if (qdcount != 1)
74|    return ARES_EBADRESP;
75|
76|
77|  /* Expand the name from the question, and skip past the question. */
78|  aptr = abuf + HFIXEDSZ;
79|  status = ares__expand_name_for_response(aptr, abuf, alen, question_hostname, &len);
80|  if (status != ARES_SUCCESS)
81|    return status;
82|  if (aptr + len + QFIXEDSZ > abuf + alen)
83|    {
84|      return ARES_EBADRESP;
85|    }
86|
87|  hostname = *question_hostname;
88|
89|  aptr += len + QFIXEDSZ;
90|
91|  /* Examine each answer resource record (RR) in turn. */
92|  for (i = 0; i < (int)ancount; i++)
93|    {
94|      /* Decode the RR up to the data field. */
95|      status = ares__expand_name_for_response(aptr, abuf, alen, &rr_name, &len);
96|      if (status != ARES_SUCCESS)
97|        {
98|          rr_name = NULL;
99|          goto failed_stat;
100|        }
101|
102|      aptr += len;
103|      if (aptr + RRFIXEDSZ > abuf + alen)
104|        {
