127|  hostent->h_addr_list = ares_malloc((naddrs + 1) * sizeof(char *));
128|  if (!hostent->h_addr_list)
129|    {
130|      goto enomem;
131|    }
132|
133|  for (i = 0; i < naddrs + 1; ++i)
134|    {
135|      hostent->h_addr_list[i] = NULL;
136|    }
137|
138|  if (ai.cnames)
