148|  hostent->h_aliases = aliases;
149|  hostent->h_addrtype = AF_INET6;
150|  hostent->h_length = sizeof(struct ares_in6_addr);
151|
152|  if (naddrs)
153|    {
154|      addrs = ares_malloc(naddrs * sizeof(struct ares_in6_addr));
155|      if (!addrs)
156|        {
157|          goto enomem;
158|        }
159|
160|      i = 0;
161|      next = ai.nodes;
